"use client"

import * as React from "react"
import { NavigationMenu as NavigationMenuPrimitive } from "radix-ui"
import { cva } from "class-variance-authority"

import { useInk, useMergedRef } from "@/lib/ink/react"
import { dropdownMenuContentRecipe } from "@/lib/ink/recipes/dropdown-menu-ink"
import { navigationMenuTriggerRecipe } from "@/lib/ink/recipes/navigation-menu-ink"
import { cn } from "@/lib/utils"

function NavigationMenu({
  className,
  children,
  viewport = true,
  ...props
}: React.ComponentProps<typeof NavigationMenuPrimitive.Root> & { viewport?: boolean }) {
  return (
    <NavigationMenuPrimitive.Root
      data-slot="navigation-menu"
      data-viewport={viewport}
      className={cn("relative z-10 flex max-w-max flex-1 items-center justify-center", className)}
      {...props}
    >
      {children}
      {viewport ? <NavigationMenuViewport /> : null}
    </NavigationMenuPrimitive.Root>
  )
}

function NavigationMenuList(props: React.ComponentProps<typeof NavigationMenuPrimitive.List>) {
  return (
    <NavigationMenuPrimitive.List
      data-slot="navigation-menu-list"
      className={cn("group flex flex-1 list-none items-center justify-center gap-1", props.className)}
      {...props}
    />
  )
}

function NavigationMenuItem(props: React.ComponentProps<typeof NavigationMenuPrimitive.Item>) {
  return <NavigationMenuPrimitive.Item data-slot="navigation-menu-item" className={cn("relative", props.className)} {...props} />
}

const navigationMenuTriggerStyle = cva(
  "group relative isolate inline-flex h-9 w-max items-center justify-center rounded-[var(--radius-sm)] px-4 py-2 text-sm font-medium outline-none transition-colors disabled:pointer-events-none disabled:opacity-50",
)

function NavigationMenuTrigger({
  className,
  children,
  ref,
  ...props
}: React.ComponentProps<typeof NavigationMenuPrimitive.Trigger>) {
  const { hostRef, hostProps, node } = useInk({
    recipe: navigationMenuTriggerRecipe,
    params: {},
    kind: "nav-trigger",
    still: true,
  })

  return (
    <NavigationMenuPrimitive.Trigger
      ref={useMergedRef<HTMLButtonElement>(hostRef, ref)}
      {...hostProps}
      data-slot="navigation-menu-trigger"
      className={cn(navigationMenuTriggerStyle(), "text-muted-foreground hover:text-foreground data-[state=open]:text-foreground", className)}
      {...props}
    >
      {node}
      <span className="relative z-[1] inline-flex items-center gap-1">
        {children}
        <span className="text-[10px] opacity-60 transition-transform group-data-[state=open]:rotate-180" aria-hidden>
          ▾
        </span>
      </span>
    </NavigationMenuPrimitive.Trigger>
  )
}

function NavigationMenuContentPanel({
  seed,
  children,
  className,
}: {
  seed?: string | number
  children: React.ReactNode
  className?: string
}) {
  const { hostRef, hostProps, node } = useInk({
    recipe: dropdownMenuContentRecipe,
    params: {},
    kind: "dropdown-menu",
    seed,
    still: true,
  })
  return (
    <div
      ref={hostRef}
      {...hostProps}
      className={cn(
        "relative isolate overflow-hidden rounded-[var(--radius-md)] shadow-[0_10px_32px_-8px_rgb(var(--sd-shade)/0.2)]",
        className,
      )}
    >
      {node}
      <div className="relative z-[1]">{children}</div>
    </div>
  )
}

function NavigationMenuContent({
  className,
  seed,
  children,
  ...props
}: React.ComponentProps<typeof NavigationMenuPrimitive.Content> & { seed?: string | number }) {
  return (
    <NavigationMenuPrimitive.Content
      data-slot="navigation-menu-content"
      className={cn(
        "absolute top-full left-0 w-full p-2 md:w-auto",
        "data-[motion^=from-]:animate-in data-[motion^=to-]:animate-out data-[motion^=from-]:fade-in data-[motion^=to-]:fade-out",
        "data-[motion=from-end]:slide-in-from-right-52 data-[motion=from-start]:slide-in-from-left-52",
        "data-[motion=to-end]:slide-out-to-right-52 data-[motion=to-start]:slide-out-to-left-52",
        className,
      )}
      {...props}
    >
      <NavigationMenuContentPanel seed={seed} className="p-4">
        {children}
      </NavigationMenuContentPanel>
    </NavigationMenuPrimitive.Content>
  )
}

function NavigationMenuViewport({
  className,
  ...props
}: React.ComponentProps<typeof NavigationMenuPrimitive.Viewport>) {
  return (
    <div className={cn("absolute top-full left-0 isolate z-50 flex justify-center")}>
      <NavigationMenuPrimitive.Viewport
        data-slot="navigation-menu-viewport"
        className={cn(
          "origin-top-center relative mt-1.5 h-[var(--radix-navigation-menu-viewport-height)] w-full overflow-hidden",
          "data-[state=open]:animate-in data-[state=closed]:animate-out data-[state=closed]:zoom-out-95 data-[state=open]:zoom-in-90",
          "md:w-[var(--radix-navigation-menu-viewport-width)]",
          className,
        )}
        {...props}
      />
    </div>
  )
}

function NavigationMenuLink({
  className,
  ...props
}: React.ComponentProps<typeof NavigationMenuPrimitive.Link>) {
  return (
    <NavigationMenuPrimitive.Link
      data-slot="navigation-menu-link"
      className={cn(
        "block rounded-[var(--radius-sm)] px-3 py-2 text-sm outline-none transition-colors",
        "hover:bg-[color-mix(in_srgb,var(--sd-rose-wash)_38%,transparent)] focus:bg-[color-mix(in_srgb,var(--sd-rose-wash)_42%,transparent)]",
        className,
      )}
      {...props}
    />
  )
}

function NavigationMenuIndicator(props: React.ComponentProps<typeof NavigationMenuPrimitive.Indicator>) {
  return (
    <NavigationMenuPrimitive.Indicator
      data-slot="navigation-menu-indicator"
      className={cn(
        "top-full z-[1] flex h-1.5 items-end justify-center overflow-hidden",
        "data-[state=visible]:animate-in data-[state=hidden]:animate-out data-[state=hidden]:fade-out data-[state=visible]:fade-in",
        props.className,
      )}
      {...props}
    >
      <div className="relative top-[60%] size-2 rotate-45 rounded-tl-sm bg-[color-mix(in_srgb,var(--sd-sand-slip)_92%,transparent)] shadow-sm" />
    </NavigationMenuPrimitive.Indicator>
  )
}

export {
  NavigationMenu,
  NavigationMenuContent,
  NavigationMenuIndicator,
  NavigationMenuItem,
  NavigationMenuLink,
  NavigationMenuList,
  NavigationMenuTrigger,
  NavigationMenuViewport,
  navigationMenuTriggerStyle,
}

import { wash } from '@/lib/ink/fills'
import { roundRectPoly } from '@/lib/ink/geom'
import { focusRing, line, underline } from '@/lib/ink/shapes'
import { defineRecipe } from '@/lib/ink/recipes'

export const navigationMenuTriggerRecipe = defineRecipe<Record<string, never>>({
  id: 'navigation-menu-trigger',
  kind: 'nav-trigger',
  layers: ['rest', 'hover', 'open', 'focus'],
  lazy: ['focus'],
  pad: 6,
  draw(ink, { w, h }, _params, ctx) {
    const baseline = h - 1.2
    const strip = roundRectPoly(2, h - 5, w - 4, 4, 2)

    ctx.lazy('focus', (fink) => {
      wash(fink, strip, 'star', { alpha: 0.14, material: 'wash', wobble: 0.5 })
      focusRing(fink, 0, 0, w, h, { r: 4, pen: 'horizonPencil.fine', opts: { alpha: 0.75, simple: true } })
    })
    if (ctx.lazyOnly) return

    ink.layer('rest', () => {
      line(ink, 2, baseline, w - 2, baseline, {
        pen: 'pencil.fine',
        opts: { alpha: 0.28, simple: true, color: 'line-soft' },
      })
    })

    ink.layer('hover', () => {
      wash(ink, strip, 'rose-wash', { alpha: 0.38, material: 'wash', wobble: 0.82 })
      line(ink, 4, baseline, w - 4, baseline, {
        pen: 'horizonPencil.fine',
        opts: { alpha: 0.5, simple: true },
      })
    })

    ink.layer('open', () => {
      wash(ink, strip, 'rose-wash', { alpha: 0.48, material: 'wash', wobble: 0.88 })
      wash(ink, strip, 'horizon', { alpha: 0.16, material: 'wash', inset: 0.3 })
      underline(ink, 3, baseline, w - 6, { pen: 'rose.fine', kind: 'single', opts: { alpha: 0.82 } })
    })
  },
})

import { wash } from '@/lib/ink/fills'
import { roundRectPoly } from '@/lib/ink/geom'
import { focusRing } from '@/lib/ink/shapes'
import { clamp } from '@/lib/ink/rng'
import { defineRecipe } from '@/lib/ink/recipes'
import { drawCompactSandSlipPanel } from '@/lib/ink/recipes/panel-wash'

export const dropdownMenuContentRecipe = defineRecipe<Record<string, never>>({
  id: 'dropdown-menu-content',
  kind: 'dropdown-menu',
  layers: ['rest'],
  pad: 8,
  draw(ink, { w, h }) {
    ink.layer('rest', () => drawCompactSandSlipPanel(ink, w, h))
  },
})

export interface DropdownMenuItemParams {
  disabled?: boolean
}

export const dropdownMenuItemRecipe = defineRecipe<DropdownMenuItemParams>({
  id: 'dropdown-menu-item',
  kind: 'menu-item',
  layers: ['rest', 'hover', 'focus', 'disabled'],
  lazy: ['focus'],
  pad: 4,
  draw(ink, { w, h }, { disabled }, ctx) {
    const r = clamp(Math.min(w, h) * 0.2, 2, 4)
    const body = roundRectPoly(0.5, 0.5, w - 1, h - 1, r)

    if (disabled) {
      if (ctx.lazyOnly) return
      ink.layer('disabled', () => {
        wash(ink, body, 'sand-shade', { alpha: 0.2, material: 'wash', wobble: 0.35 })
      })
      return
    }

    ctx.lazy('focus', (fink) => {
      wash(fink, body, 'rose-wash', { alpha: 0.38, material: 'wash', wobble: 0.65 })
      focusRing(fink, 0, 0, w, h, { r, pen: 'horizonPencil.fine', opts: { alpha: 0.7, simple: true } })
    })
    if (ctx.lazyOnly) return

    ink.layer('hover', () => {
      wash(ink, body, 'rose-wash', { alpha: 0.42, material: 'wash', wobble: 0.72 })
    })
  },
})

import { roundRectPoly } from '@/lib/ink/geom'
import { box } from '@/lib/ink/shapes'
import { clamp } from '@/lib/ink/rng'
import type { Ink } from '@/lib/ink/builder'
import { softFill } from '@/lib/ink/recipes/wash-utils'

export type PanelTone = 'default' | 'lifted'

/** Compact sand-slip panel (Tooltip / Toast). */
export function drawCompactSandSlipPanel(ink: Ink, w: number, h: number) {
  const r = clamp(Math.min(w, h) * 0.1, 4, 7)
  const inset = 0.55
  const body = roundRectPoly(inset, inset, w - 2 * inset, h - 2 * inset, r)

  ink.part('fill', () => {
    softFill(ink, body, [
      { color: 'sand-slip', alpha: 0.82, wobble: 0.48 },
      { color: 'sand', alpha: 0.28, inset: 0.9, wobble: 0.55 },
      { color: 'wash-gold', alpha: 0.06, inset: 1.6, wobble: 0.9 },
    ])
  })
  box(ink, 0.55, 0.55, w - 1.1, h - 1.1, {
    pen: 'pencil.fine',
    corner: r,
    loose: 0.95,
    opts: { alpha: 0.48, wobble: 0.38, simple: w > 280 },
  })
  box(ink, 1.1, 1.1, w - 2.2, h - 2.2, {
    pen: 'ink.fine',
    corner: Math.max(2, r - 1),
    loose: 1,
    opts: { alpha: 0.18, wobble: 0.42, simple: true, color: 'line-soft' },
  })
}

/** Sand-slip panel fill + double loose border (Card / Dialog / Popover). */
export function drawSandSlipPanel(ink: Ink, w: number, h: number, tone: PanelTone = 'default') {
  const r = clamp(Math.min(w, h) * 0.04, 5, 12)
  const inset = 0.7
  const body = roundRectPoly(inset, inset, w - 2 * inset, h - 2 * inset, r)

  ink.part('fill', () => {
    softFill(ink, body, [
      { color: 'sand-slip', alpha: tone === 'lifted' ? 0.9 : 0.78, wobble: 0.5 },
      { color: 'sand', alpha: 0.32, inset: 1.2, wobble: 0.65 },
      { color: 'wash-gold', alpha: 0.08, inset: 2.4, wobble: 1.1 },
    ])
  })
  box(ink, 0.65, 0.65, w - 1.3, h - 1.3, {
    pen: 'pencil.fine',
    corner: r,
    loose: 1.15,
    opts: { alpha: 0.52, wobble: 0.42, simple: w > 420 },
  })
  box(ink, 1.4, 1.4, w - 2.8, h - 2.8, {
    pen: 'ink.fine',
    corner: Math.max(2, r - 1),
    loose: 1.25,
    opts: { alpha: 0.22, wobble: 0.5, simple: true, color: 'line-soft' },
  })
}

import type { Ink } from '@/lib/ink/builder'
import type { Pt } from '@/lib/ink/types'
import type { PaintKey } from '@/lib/ink/paint'
import { wash } from '@/lib/ink/fills'

export function softFill(
  ink: Ink,
  body: Pt[],
  layers: Array<{ color: PaintKey; alpha: number; inset?: number; wobble?: number }>,
) {
  for (const layer of layers) {
    wash(ink, body, layer.color, {
      alpha: layer.alpha,
      inset: layer.inset ?? 0.4,
      wobble: layer.wobble ?? 0.95,
      material: 'wash',
    })
  }
}
